b=r.folder(55);worlds=[]
for row in itertools.permutations('GEBJ'):
 # Positions: general,personnel,sales,materials. G only licence; B only non-new.
 if row.index('G') not in [0,1]:continue
 if sum(x in 'BJ' for x in row[2:])!=1:continue
 if row.index('J') not in [1,3] and row.index('J')!=2:continue
 if sum(x!='B' for x in row[2:])!=1:continue
 worlds.append(row)
final=[w for w in worlds if (w[1] in 'BJ')==(w[2] in 'BJ')]
assert set(worlds)=={('G','J','E','B'),('G','J','B','E')} and final==[('G','J','B','E')]
